#include <iostream>
#include <cstdio>
#include <cstring>
#include <queue>
#include <vector>
#include <cassert>
#include <cmath>
#include <string>
#include <algorithm>

using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef long double ld;

const double EPS = 1e-9;
const double PI = acos(-1.0);
const int MOD = 1000000007;
const int INF = 2000000000;
const int MAXN = 210;
const int MAXM = 2 * MAXN * MAXN;
const int dx[] = {1, 0, 0, -1};
const int dy[] = {0, 1, -1, 0};
const int SRC = MAXN - 2;
const int DST = MAXN - 1;

inline int sq(int x) { return x * x; }

struct FlowNet {
    int to[MAXM];
    int f[MAXM], c[MAXM];
    int ecnt;

    vector<int> g[MAXN];
    bool vis[MAXN];

    FlowNet() : ecnt(0) {}

    void connect(int u, int v, int cap) {
        to[ecnt] = v;
        f[ecnt] = 0;
        c[ecnt] = cap;
        g[u].push_back(ecnt++);

        to[ecnt] = u;
        f[ecnt] = 0;
        c[ecnt] = 0;
        g[v].push_back(ecnt++);
    }

    bool dfs(int v, int sink, int amt) {
        if (v == sink) return true;
        vis[v] = true;

        for (int idx : g[v]) {
            if (!vis[to[idx]] && c[idx] - f[idx] >= amt &&
                dfs(to[idx], sink, amt)) {
                f[idx] += amt;
                f[idx ^ 1] -= amt;
                return true;
            }
        }
        return false;
    }

    int solve(int src, int sink) {
        int amt = 1 << 30;
        int res = 0;

        while (amt > 0) {
            if (dfs(src, sink, amt)) {
                res += amt;
            } else {
                amt >>= 1;
            }
            memset(vis, false, sizeof vis);
        }
        return res;
    }
};

FlowNet net;

int N, T;
char G1[15][15];
char G2[15][15];
int d[15][15];
bool mark[15][15];

bool ok(int x, int y) {
    return 0 <= x && x < N &&
           0 <= y && y < N &&
           G1[x][y] != 'Y' &&
           G1[x][y] != 'Z';
}

void bfsZ(int sx, int sy) {
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            d[i][j] = INF;

    queue<int> qx, qy;
    d[sx][sy] = 0;
    qx.push(sx);
    qy.push(sy);

    while (!qx.empty()) {
        assert(!qy.empty());
        int cx = qx.front(); qx.pop();
        int cy = qy.front(); qy.pop();

        for (int k = 0; k < 4; ++k) {
            int nx = cx + dx[k];
            int ny = cy + dy[k];
            if (ok(nx, ny) && d[nx][ny] == INF) {
                d[nx][ny] = d[cx][cy] + 1;
                qx.push(nx);
                qy.push(ny);
            }
        }
    }
}

void bfsS(int sx, int sy) {
    queue<int> qx, qy, ql;
    memset(mark, false, sizeof mark);

    mark[sx][sy] = true;
    qx.push(sx);
    qy.push(sy);
    ql.push(0);

    while (!qx.empty()) {
        assert(!qy.empty());
        int cx = qx.front(); qx.pop();
        int cy = qy.front(); qy.pop();
        int lv = ql.front(); ql.pop();

        if (isdigit(G2[cx][cy]) && G2[cx][cy] != '0') {
            net.connect(sx * N + sy, sq(N) + 1 + cx * N + cy, INF);
        }

        if (lv >= T) continue;

        for (int k = 0; k < 4; ++k) {
            int nx = cx + dx[k];
            int ny = cy + dy[k];

            if (ok(nx, ny) && !mark[nx][ny]) {
                if (d[nx][ny] > lv + 1) {
                    qx.push(nx);
                    qy.push(ny);
                    ql.push(lv + 1);
                } else if (d[nx][ny] > lv && isdigit(G2[nx][ny]) && G2[nx][ny] != '0') {
                    net.connect(sx * N + sy, sq(N) + 1 + nx * N + ny, INF);
                }
                mark[nx][ny] = true;
            }
        }
    }
}

void setup() {
    int sx = -1, sy = -1;
    for (int i = 0; i < N && sx == -1; ++i)
        for (int j = 0; j < N && sx == -1; ++j)
            if (G1[i][j] == 'Z') {
                sx = i; sy = j;
            }

    bfsZ(sx, sy);

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(G1[i][j]) && G1[i][j] != '0')
                net.connect(SRC, i * N + j, G1[i][j] - '0');

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(G2[i][j]) && G2[i][j] != '0')
                net.connect(i * N + j + sq(N) + 1, DST, G2[i][j] - '0');

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(G1[i][j]) && G1[i][j] != '0')
                bfsS(i, j);
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in", "r", stdin);
#endif

    scanf("%d %d", &N, &T);
    scanf("\n");
    for (int i = 0; i < N; ++i) gets(G1[i]);
    scanf("\n");
    for (int i = 0; i < N; ++i) gets(G2[i]);

    setup();
    printf("%d\n", net.solve(SRC, DST));

    return 0;
}
